-- Execute the initial anonymous block successfully BEFORE the DROP statements.
USE auxiliares;
DELIMITER $$
BEGIN NOT ATOMIC
 IF NOT (((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND ((TRIGGER_NAME='TRG_FB_CONSULTAS_VERSION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='4be4ff341c0d2c8967f7985a96bcaf3942db6c43379747d8f506f71687bbe327') OR (TRIGGER_NAME='TRG_FB_CONSULTAS_HIST_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='ce2c9e18dc0da7709ad1735f891c390fdd15174f699f29b85b7924c5e4cd149f') OR (TRIGGER_NAME='TRG_FB_CONSULTAS_HIST_UPDATE' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='9bff2ba5668204256352beda8a166936ff8d268b58fbb68794dd2bba4c411f3a') OR (TRIGGER_NAME='TRG_FB_CONTACTOS_VERSION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='2de5fa7b0009b50cb42a0c852c27548246dbe587a5796b2b313e078060920c74') OR (TRIGGER_NAME='TRG_FB_CONTACTOS_HIST_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='d085feee68a4f55a8e331a2d93201ec0f7e9b5876fffe66cae9fa7f2e037bc5a') OR (TRIGGER_NAME='TRG_FB_CONTACTOS_HIST_UPDATE' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='07c8d37e9c96af552252e7dedd33da57cb878b58f07875bddcf8b4599fe93019') OR (TRIGGER_NAME='TRG_FB_DOMICILIOS_VERSION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='e1267ce29eec63181bf8fba5a025f2bcce7cbe8e94c3fff7c19ccee557525fde') OR (TRIGGER_NAME='TRG_FB_DOMICILIOS_HIST_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='bd5bcf9be29391305c79963508441c8f8a309bdf35946e88724d839c4929a519') OR (TRIGGER_NAME='TRG_FB_DOMICILIOS_HIST_UPDATE' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='cdfca9635b702b41538c633ae0055f55b6a01d3a14752bf98bde5143752d2193') OR (TRIGGER_NAME='TRG_FB_CONSULTA_CONTACTO_ALTA' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='c1f3cb6c067efb0c354039eba6f96fbe5b946b517da1cdd0bc6f4b736c95b19c') OR (TRIGGER_NAME='TRG_FB_CONSULTA_CONTACTO_EDICION' AND SHA2(REPLACE(ACTION_STATEMENT,CHAR(13),''),256)='7985a6b7759a3c480c1935f4986174927a41415bd584b202324e35fb97a26166')))=11) AND ((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='FB_PERSONAS' AND INDEX_NAME='UK_FB_PERSONAS_DOCUMENTO' AND NON_UNIQUE=0 AND SEQ_IN_INDEX=2 AND COLUMN_NAME='DOCUMENTO_IDENTIDAD_UNICA')=1) AND ((SELECT COUNT(*) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN ('FK_71_QUERY_CP','FK_71_CONTACTO_IDENTIDAD','FK_71_DOM_CP','FK_71_DOM_IDENTIDAD','FK_71_VINCULO_CP','FK_71_VINCULO_IDENTIDAD','FK_71_RECEIPT_ACTOR','FK_71_RECEIPT_QUERY'))=8)) OR COALESCE((SELECT REVISION FROM FB_MODELO_REVISION WHERE MODELO='consultas'),'')<>'7.1' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_NO_REVISADO'; END IF;
END$$
